{"python":"def pilot_policy(trace):
    import json
    from typing import Set

    def parse_action(action_str: str) -> dict:
        return json.loads(action_str)

    def get_categories_in_label(label) -> Set[str]:
        if hasattr(label, 'subset'):
            return label.subset
        return set()

    def is_slot_allowed(slot_name: str, categories: Set[str], policy: dict) -> bool:
        if slot_name not in policy:
            return True
        allowed = set(policy[slot_name])
        return categories.issubset(allowed)

    last_idx = len(trace) - 1
    action, label = trace[last_idx]
    params = parse_action(action.arguments)
    tool_name = action.name
    label_categories = get_categories_in_label(label)

    policy = {"slot:audit": ["DIAGNOSIS", "AUTH"], "slot:lab": ["PATIENT", "AUTH"], "slot:public": ["PATIENT", "DIAGNOSIS", "AUTH"], "slot:research": ["PATIENT", "UNVERIFIED"], "slot:scheduler": ["DIAGNOSIS", "AUTH"]}

    if tool_name == "intake/register_material":
        category = params.get("category", "")
        if category not in label_categories:
            raise PolicyViolation(f"Category {category} not in label")
        if not is_slot_allowed("slot:referral", {category}, policy):
            raise PolicyViolation(f"Category {category} not allowed in slot:referral")
    elif tool_name == "clinician/review_referral":
        if not is_slot_allowed("slot:reviewed", label_categories, policy):
            raise PolicyViolation(f"Categories {label_categories} not allowed in slot:reviewed")
    elif tool_name == "coordinator/assemble_referral":
        source = params.get("source", "")
        if source not in ["reviewed", "referral"]:
            raise PolicyViolation(f"Invalid source {source}")
        if not is_slot_allowed("slot:packet", label_categories, policy):
            raise PolicyViolation(f"Categories {label_categories} not allowed in slot:packet")
    elif tool_name in ["care/route_referral", "research/route_referral"]:
        team = "care" if tool_name.startswith("care") else "research"
        destination = params.get("destination", "")
        source = params.get("source", "")
        attachment = params.get("attachment", "")
        record = params.get("record", "")

        destination_map = {
            "care": {"local": "slot:hospital", "partner": "slot:scheduler", "release": "slot:public"},
            "research": {"local": "slot:hospital", "partner": "slot:research", "release": "slot:lab"}
        }
        record_map = {
            "audit": "slot:audit",
            "public": "slot:public",
            "partner": {"care": "slot:scheduler", "research": "slot:research"}
        }

        dest_slot = destination_map[team].get(destination)
        if not dest_slot:
            raise PolicyViolation(f"Invalid destination {destination} for {team}")

        if not is_slot_allowed(dest_slot, label_categories, policy):
            raise PolicyViolation(f"Categories {label_categories} not allowed in {dest_slot}")

        if record != "none":
            rec_slot = record_map.get(record)
            if isinstance(rec_slot, dict):
                rec_slot = rec_slot[team]
            if not is_slot_allowed(rec_slot, label_categories, policy):
                raise PolicyViolation(f"Categories {label_categories} not allowed in record slot {rec_slot}")

    return None"}
